// Central Error Handler for Gorgias Terminal
// Captures errors from any node and formats for logging/notification

const items = $input.all();
const errors = [];

// Get correlation ID from Parse Slack node
let correlationId = 'unknown';
try {
  correlationId = $('Parse Slack').first().json.correlation_id;
} catch (e) {
  console.log('⚠️ Could not retrieve correlation_id');
}

// Get user ID from Parse Slack node
let userId = 'unknown';
try {
  userId = $('Parse Slack').first().json.user_id;
} catch (e) {
  console.log('⚠️ Could not retrieve user_id');
}

// Process each error
for (const item of items) {
  const error = {
    correlation_id: correlationId,
    user_id: userId,
    timestamp: new Date().toISOString(),
    node: item.json.node || 'unknown',
    action: item.json.action || 'unknown',
    error_message: item.json.error?.message || item.json.message || 'Unknown error',
    error_code: item.json.error?.code || null,
    error_type: item.json.error?.type || 'UnknownError',
    http_status: item.json.httpCode || null,
    request_data: item.json.request || null,
    response_data: item.json.response || null,
    stack_trace: item.json.error?.stack || null
  };

  errors.push(error);

  // Log to console for n8n logs
  console.error('❌ Gorgias Terminal Error:', {
    correlation_id: error.correlation_id,
    node: error.node,
    action: error.action,
    error: error.error_message
  });
}

// Return errors for downstream processing
return errors.map(error => ({ json: error }));
